def audit_and_repair_primary_shares(apps, schema_editor):
    PropertyContract = apps.get_model('real_estate', 'PropertyContract')
    # 1. تدقيق السجلات التاريخية الفردية (بدون شركاء) وتصحيح نسبتها إلى 100%
    # في حالة عدم وجود شركاء، تؤول الملكية بالكامل 100% للمشتري الرئيسي
    PropertyContract.objects.filter(
        models.Q(primary_owner_share__lt=0) | models.Q(primary_owner_share__gt=100),
        co_owners__isnull=True
    ).update(primary_owner_share=Decimal('100.00'))

    # 2. العقود التي تحتوي على شركاء وبها نسب شاذة:
    # يُحظر التعديل العشوائي إلى 100% لتفادي زيادة إجمالي الملكية إلى أكثر من 100% (مثل حالة 250%)
    # تُسجل الحالات المخالفة في تقرير التدقيق لمراجعتها وتصحيحها محاسبياً ومستندياً
    shared_anomalies = PropertyContract.objects.filter(
        models.Q(primary_owner_share__lt=0) | models.Q(primary_owner_share__gt=100),
        co_owners__isnull=False
    ).distinct()
    if shared_anomalies.exists():
        import logging
        logger = logging.getLogger('real_estate.migration_0030')
        for c in shared_anomalies:
            logger.warning(
                f"[Preflight Audit 0030] Contract ID={c.id} ({c.contract_number}) has out-of-range "
                f"primary_owner_share={c.primary_owner_share}. Requires manual reconciliation."
            )


